import{_ as r,l as n,o as a,c as i,v as l,p as s,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"循环展开与剥离","description":"","frontmatter":{"title":"循环展开与剥离","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/loop-unroll-peel.md","filePath":"cs/loop-unroll-peel.md","lastUpdated":1789023840000}'),h={name:"cs/loop-unroll-peel.md"};function _(u,e,m,E,k,f){const t=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=l('<h1 id="循环展开与剥离" tabindex="-1">循环展开与剥离 <a class="header-anchor" href="#循环展开与剥离" aria-label="Permalink to &quot;循环展开与剥离&quot;">​</a></h1><div class="epigraph"><p>展开把循环体复制 $k$ 次，减少分支与暴露调度窗口；剥离处理不对齐的头几圈，使主循环满足向量或缓存假设。</p><footer>—— 据 Allen and Cocke 变换目录；龙书循环展开；Kennedy and Allen, Optimizing Compilers for Modern Architectures 整理</footer></div><p>上一课<a href="/cs/strength-reduction-iv">强度削弱</a>减每圈算术。缺口是<strong>圈结构本身</strong>：展开（unroll）、剥离（peel）、余数循环。本课钉何时复制体，不写自动向量化的依赖分析——后课。也不把展开当软件流水。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每圈一次条件跳，对小体是开销；超标量要更多独立指令。展开 \\(k\\)：计数器步进 \\(k\\)，体复制，IV 已削弱则可直接写 \\(k\\) 份地址。余数：<code>n%k</code> 用剥离或收尾循环。缺口是<strong>因子 \\(k\\) 与代码大小</strong>，不是 IV 识别。</p><p>完全展开：行程编译期常量则变成直线代码，再 SCCP/DCE。</p><h3 id="剥离不是展开" tabindex="-1">剥离不是展开 <a class="header-anchor" href="#剥离不是展开" aria-label="Permalink to &quot;剥离不是展开&quot;">​</a></h3><p>剥离：先跑 1 至若干圈（处理对齐、第一次迭代的特殊别名），再进主循环。展开是主循环体内复制。常组合：剥到对齐，再按向量宽度展开。</p><p><span class="marginnote">Kennedy–Allen 的教材。龙书。PGO 后课用轮廓选 \\(k\\)。本课静态启发：体大小、行程估计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计：体指令数 × \\(k\\) 是否超过阈值。已知 <code>n</code> 则选整除的 \\(k\\)。未知则收尾循环。剥：对「首圈必执行的不变量 store」有时比 LICM 更易证明。</p>',11)),(a(),s(c,null,{default:o(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20PEEL%5B%22%E5%89%A5%E7%A6%BB%E5%AF%B9%E9%BD%90%22%5D%0A%20%20PEEL%20--%3E%20UN%5B%22%E5%B1%95%E5%BC%80%20k%22%5D%0A%20%20UN%20--%3E%20EPIL%5B%22%E6%94%B6%E5%B0%BE%E4%BD%99%E6%95%B0%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<p>与寄存器压力：展开拉长存活区间，着色更难——后课线性扫描会痛。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不要展开带可变行程且巨大的体。调试：行号映射多份体到同一源行，DWARF 后课。不要改变浮点归约顺序除非 fast-math。</p><p>并行：展开不创造并行；只给调度与向量化窗口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多面体。后课默认：小体、常行程可展开；对齐用剥离。下一课交换与分块：改迭代嵌套的顺序与粒度。</p><p>也不把展开当混淆（故意胀代码）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>展开复制体、降分支、开调度窗口；余数要收尾。</li><li>剥离服务对齐与首圈特例。</li><li>\\(k\\) 受代码大小与寄存器压力约束。</li><li>出处：Allen and Cocke；Kennedy and Allen；龙书。</li></ul>',9))])}const P=r(h,[["render",_]]);export{B as __pageData,P as default};
